/** The word with an example sentence filled in, when it has none of its own. */
export function withExampleSentence<T extends Word>(word: T): T {
  if (word.exampleSentence) return word;
  const example = EXAMPLES[word.id];
  if (!example) return word;
  const [thai, romanization, english] = example;
  const exampleSentence: ExampleSentence = { thai, romanization, english };
  return { ...word, exampleSentence };
}
